/* Connected Remote Video Conference Desk
 * Self-contained Canvas artwork. Time is in seconds; the cycle is 20 seconds.
 * Call draw(ctx, time, width, height). Recommended frame rate: 60 fps.
 * Video encoder target and required minimum: 100000000 bits/second (100 Mbps).
 * Verify the encoded video's bitrate in the export application.
 * JavaScript frames themselves do not have a video bitrate.
 */
const REMOTE_SCENE_01 = (() => {
  'use strict';
  const C = {"bg": "#EEF3F2", "paper": "#FFFFFF", "ink": "#243D43", "muted": "#71878A", "line": "#CCDAD9", "body": "#F0F6F5", "body2": "#DFE9E7", "side": "#4C6971", "accent": "#4B8B8C", "green": "#5D9074", "red": "#B87572", "desk": "#F8FAF7", "desk2": "#DFE9E7"};
  const TAU = Math.PI * 2;
  const fonts = 'Arial, Helvetica, "Nimbus Sans", "DejaVu Sans", sans-serif';
  const measurements = new Map();
  const clamp = v => Math.max(0, Math.min(1, v));
  const ease = v => { v = clamp(v); return v < .5 ? 4 * v * v * v : 1 - Math.pow(-2 * v + 2, 3) / 2; };
  const phase = (t, a, b) => ease((t - a) / (b - a));
  const mix = (a, b, p) => a + (b - a) * p;
  const travel = (t, a, b, c, d) => phase(t, a, b) * (1 - phase(t, c, d));
  const windowAlpha = (t, a, b, c, d) => travel(t, a, b, c, d);
  function blend(a, b, p) {
    p = clamp(p);
    const ca = parseInt(a.slice(1), 16), cb = parseInt(b.slice(1), 16);
    const r = Math.round(mix(ca >> 16, cb >> 16, p));
    const g = Math.round(mix((ca >> 8) & 255, (cb >> 8) & 255, p));
    const bl = Math.round(mix(ca & 255, cb & 255, p));
    return '#' + ((r << 16) | (g << 8) | bl).toString(16).padStart(6, '0');
  }
  function layer(ctx, opacity, fn) {
    if (opacity <= .00001) return;
    ctx.save(); ctx.globalAlpha *= clamp(opacity); fn(); ctx.restore();
  }
  function roundedPath(ctx, x, y, w, h, r) {
    r = Math.max(0, Math.min(r, w / 2, h / 2));
    ctx.beginPath(); ctx.moveTo(x + r, y); ctx.lineTo(x + w - r, y);
    ctx.quadraticCurveTo(x + w, y, x + w, y + r);
    ctx.lineTo(x + w, y + h - r); ctx.quadraticCurveTo(x + w, y + h, x + w - r, y + h);
    ctx.lineTo(x + r, y + h); ctx.quadraticCurveTo(x, y + h, x, y + h - r);
    ctx.lineTo(x, y + r); ctx.quadraticCurveTo(x, y, x + r, y); ctx.closePath();
  }
  function box(ctx, x, y, w, h, r, fill, stroke = C.ink, lw = 3) {
    roundedPath(ctx, x, y, w, h, r);
    if (fill) { ctx.fillStyle = fill; ctx.fill(); }
    if (stroke && lw > 0) { ctx.strokeStyle = stroke; ctx.lineWidth = lw; ctx.stroke(); }
  }
  function line(ctx, x1, y1, x2, y2, color = C.ink, width = 3) {
    ctx.beginPath(); ctx.moveTo(x1, y1); ctx.lineTo(x2, y2); ctx.strokeStyle = color; ctx.lineWidth = width; ctx.stroke();
  }
  function circle(ctx, x, y, r, fill, stroke = null, width = 3) {
    ctx.beginPath(); ctx.arc(x, y, r, 0, TAU);
    if (fill) { ctx.fillStyle = fill; ctx.fill(); }
    if (stroke) { ctx.strokeStyle = stroke; ctx.lineWidth = width; ctx.stroke(); }
  }
  function polygon(ctx, points, fill, stroke = C.ink, width = 3) {
    ctx.beginPath(); ctx.moveTo(points[0][0], points[0][1]);
    for (let i = 1; i < points.length; i++) ctx.lineTo(points[i][0], points[i][1]);
    ctx.closePath(); if (fill) { ctx.fillStyle = fill; ctx.fill(); }
    if (stroke) { ctx.strokeStyle = stroke; ctx.lineWidth = width; ctx.stroke(); }
  }
  function matte(ctx, x, y, w, h, a, b) {
    const g = ctx.createLinearGradient(x, y, x + w, y + h); g.addColorStop(0, a); g.addColorStop(1, b); return g;
  }
  function label(ctx, value, x, y, size = 20, color = C.ink, align = 'left', maxWidth = 0, weight = 600) {
    const str = String(value);
    let fontSize = size, m;
    while (true) {
      ctx.font = weight + ' ' + fontSize.toFixed(2) + 'px ' + fonts;
      const key = ctx.font + '|' + str;
      m = measurements.get(key);
      if (!m) { const a = ctx.measureText(str); m = {w: a.width, a: a.actualBoundingBoxAscent || fontSize * .75, d: a.actualBoundingBoxDescent || 0}; measurements.set(key, m); }
      if (!maxWidth || m.w <= maxWidth || fontSize <= 12) break;
      fontSize = Math.max(12, fontSize * Math.min(.97, maxWidth / m.w));
    }
    ctx.fillStyle = color; ctx.textAlign = align; ctx.textBaseline = 'alphabetic';
    ctx.fillText(str, x, y + (m.a - m.d) / 2);
  }
  function check(ctx, x, y, size, color = C.green, p = 1) {
    const pts = [[x - size * .42, y], [x - size * .08, y + size * .30], [x + size * .48, y - size * .32]];
    ctx.beginPath(); ctx.moveTo(...pts[0]);
    if (p < .4) ctx.lineTo(mix(pts[0][0], pts[1][0], p / .4), mix(pts[0][1], pts[1][1], p / .4));
    else { ctx.lineTo(...pts[1]); ctx.lineTo(mix(pts[1][0], pts[2][0], (p - .4) / .6), mix(pts[1][1], pts[2][1], (p - .4) / .6)); }
    ctx.strokeStyle = color; ctx.lineWidth = Math.max(2.5, size * .14); ctx.stroke();
  }
  function activity(ctx, x, y, t, r = 12, color = C.accent) {
    circle(ctx, x, y, r, null, C.line, 2.5);
    const angle = TAU * (t / 5);
    ctx.beginPath(); ctx.arc(x, y, r, angle, angle + Math.PI * .70); ctx.strokeStyle = color; ctx.lineWidth = 3; ctx.stroke();
  }
  const layout = {"x": 0, "y": 0, "w": 1180, "h": 1080, "designWidth": 1180, "designHeight": 1080};
  function heading(ctx, title, subtitle, t) {
    label(ctx, 'REMOTE TEAM WORKSPACE', 95, 81, 14, C.muted, 'left', 860, 700);
    label(ctx, title, 95, 130, 35, C.ink, 'left', 990, 700);
    label(ctx, subtitle, 95, 176, 18, C.muted, 'left', 982, 400);
    activity(ctx, 1090, 82, t, 11);
  }
  function wave(ctx, x, y, w, h, t, offset = 0, strength = 1) {
    const n = 13, gap = w / (n * 2.4), barW = (w - gap * (n - 1)) / n;
    for (let i = 0; i < n; i++) {
      const a = .32 + .68 * (.5 + .5 * Math.sin(TAU * t / 2.5 + offset + i * .61));
      const hh = Math.max(2, h * a);
      box(ctx, x + i * (barW + gap), y + (h - hh) / 2, barW, hh, Math.min(3, barW / 2), blend(C.line, C.accent, strength), null);
    }
  }
  function icon(ctx, name, x, y, s = 24, color = C.ink) {
    const k = s / 24;
    ctx.save(); ctx.translate(x, y); ctx.scale(k, k);
    if (name === 'mic') {
      box(ctx, -4, -10, 8, 13, 4, null, color, 2);
      ctx.beginPath(); ctx.moveTo(-8, -1); ctx.lineTo(-8, 2); ctx.quadraticCurveTo(-8, 8, 0, 8); ctx.quadraticCurveTo(8, 8, 8, 2); ctx.lineTo(8, -1); ctx.strokeStyle = color; ctx.lineWidth = 2; ctx.stroke();
      line(ctx, 0, 8, 0, 11, color, 2); line(ctx, -4, 11, 4, 11, color, 2);
    } else if (name === 'video') {
      box(ctx, -11, -7, 15, 14, 3, null, color, 2);
      polygon(ctx, [[4, -3], [11, -7], [11, 7], [4, 3]], null, color, 2);
    } else if (name === 'share') {
      box(ctx, -10, -6, 20, 14, 3, null, color, 2);
      line(ctx, 0, 4, 0, -10, color, 2); line(ctx, 0, -10, -4, -6, color, 2); line(ctx, 0, -10, 4, -6, color, 2);
    } else if (name === 'lock') {
      ctx.beginPath(); ctx.arc(0, -3, 5, Math.PI, TAU); ctx.strokeStyle = color; ctx.lineWidth = 2; ctx.stroke();
      box(ctx, -8, -2, 16, 13, 3, null, color, 2); circle(ctx, 0, 4, 1.5, color);
    } else if (name === 'calendar') {
      box(ctx, -10, -9, 20, 19, 3, null, color, 2); line(ctx, -9, -3, 9, -3, color, 2);
      line(ctx, -5, -12, -5, -7, color, 2); line(ctx, 5, -12, 5, -7, color, 2);
      box(ctx, -5, 1, 4, 4, 1, color, null); box(ctx, 2, 1, 4, 4, 1, color, null);
    } else if (name === 'folder') {
      polygon(ctx, [[-11, -7], [-2, -7], [1, -3], [11, -3], [11, 9], [-11, 9]], null, color, 2);
    } else if (name === 'stop') {
      box(ctx, -6, -6, 12, 12, 3, color, null);
    } else {
      box(ctx, -10, -8, 20, 14, 2, null, color, 2); line(ctx, -3, 6, -3, 10, color, 2); line(ctx, 3, 6, 3, 10, color, 2); line(ctx, -6, 10, 6, 10, color, 2);
    }
    ctx.restore();
  }
  function controls(ctx, x, y, w, t) {
    const names = ['mic', 'video', 'share', 'lock', 'stop'], bw = 43, gap = 13;
    const start = x + (w - (bw * 5 + gap * 4)) / 2;
    names.forEach((name, i) => {
      box(ctx, start + i * (bw + gap), y, bw, 28, 8, name === 'stop' ? blend(C.paper, C.red, .12) : C.body, null);
      icon(ctx, name, start + i * (bw + gap) + bw / 2, y + 14, 16, name === 'stop' ? C.red : C.ink);
    });
  }
  function deviceGlyph(ctx, x, y, w = 66, h = 43) {
    box(ctx, x, y, w, h, 5, C.body, C.ink, 2);
    box(ctx, x + 5, y + 5, w - 10, h - 12, 2, blend(C.paper, C.accent, .12), null);
    polygon(ctx, [[x - 6, y + h], [x + w + 6, y + h], [x + w + 2, y + h + 7], [x - 2, y + h + 7]], C.body2, C.ink, 2);
  }
  function meetScreen(ctx, x, y, w, h, t, opt = {}) {
    label(ctx, opt.title || 'TEAM SESSION', x + 16, y + 22, 15, C.ink, 'left', w - 152, 700);
    activity(ctx, x + w - 22, y + 21, t, 7);
    const gap = 12, tw = (w - 36 - gap) / 2, th = (h - 99 - gap) / 2;
    for (let i = 0; i < 4; i++) {
      const xx = x + 18 + (i % 2) * (tw + gap), yy = y + 49 + Math.floor(i / 2) * (th + gap);
      const p = travel(t, 2.5 + i * 1.1, 4 + i * 1.1, 17.1, 19.8);
      box(ctx, xx, yy, tw, th, 11, blend(C.paper, C.accent, p * .065), blend(C.line, C.accent, p * .45), 2);
      label(ctx, 'ROOM ' + String(i + 1).padStart(2, '0'), xx + 13, yy + 17, 13, C.muted, 'left', tw - 45, 700);
      circle(ctx, xx + tw - 15, yy + 17, 4, blend(C.line, C.green, p));
      deviceGlyph(ctx, xx + 15, yy + 39, 64, 40);
      layer(ctx, Math.abs(2 * p - 1), () => label(ctx, p > .5 ? 'CONNECTED' : 'LINK READY', xx + 95, yy + 62, 13, C.ink, 'left', tw - 108, 600));
      wave(ctx, xx + 14, yy + th - 23, tw - 28, 14, t, i * .71, .45 + .55 * p);
    }
    controls(ctx, x, y + h - 35, w, t);
  }
  function miniScreen(ctx, x, y, w, h, t, title = 'TEAM LINK') {
    label(ctx, title, x + 13, y + 19, 13, C.ink, 'left', w - 44, 700);
    circle(ctx, x + w - 18, y + 19, 3, C.green);
    const gap = 9, cw = (w - 35) / 2;
    box(ctx, x + 13, y + 37, cw, Math.max(35, h - 78), 7, C.body, C.line, 1.5);
    box(ctx, x + 13 + cw + gap, y + 37, cw, Math.max(35, h - 78), 7, C.body, C.line, 1.5);
    icon(ctx, 'device', x + 13 + cw / 2, y + 37 + Math.max(35, h - 78) / 2, 25, C.accent);
    wave(ctx, x + 22 + cw + gap, y + 48, cw - 18, Math.max(15, h - 102), t, .3);
    wave(ctx, x + 13, y + h - 24, w - 26, 12, t, 1);
  }
  function monitor(ctx, x, y, w, h, t, fn = meetScreen) {
    const mid = x + w / 2;
    polygon(ctx, [[mid - 29, y + h - 1], [mid + 29, y + h - 1], [mid + 45, y + h + 103], [mid - 45, y + h + 103]], C.body2, C.ink, 3);
    box(ctx, mid - 118, y + h + 100, 236, 18, 8, C.body, C.ink, 3);
    box(ctx, x, y, w, h, 22, matte(ctx, x, y, w, h, C.body, C.body2), C.ink, 4);
    const sx = x + 17, sy = y + 17, sw = w - 34, sh = h - 48;
    box(ctx, sx, sy, sw, sh, 11, C.paper, C.ink, 2);
    ctx.save(); roundedPath(ctx, sx + 1, sy + 1, sw - 2, sh - 2, 10); ctx.clip(); fn(ctx, sx, sy, sw, sh, t); ctx.restore();
    circle(ctx, mid, y + h - 14, 3, C.accent);
    box(ctx, mid - 40, y - 18, 80, 17, 7, C.side, C.ink, 2.5);
    circle(ctx, mid, y - 9.5, 4.5, C.paper, C.ink, 1.5);
    circle(ctx, mid + 26, y - 9.5, 2, C.accent);
  }
  function laptop(ctx, x, y, w, h, t, fn = miniScreen) {
    box(ctx, x, y, w, h, 13, matte(ctx, x, y, w, h, C.body, C.body2), C.ink, 3.5);
    circle(ctx, x + w / 2, y + 7, 2, C.muted);
    const sx = x + 11, sy = y + 17, sw = w - 22, sh = h - 30;
    box(ctx, sx, sy, sw, sh, 6, C.paper, C.ink, 1.5);
    ctx.save(); roundedPath(ctx, sx + 1, sy + 1, sw - 2, sh - 2, 5); ctx.clip(); fn(ctx, sx, sy, sw, sh, t); ctx.restore();
    polygon(ctx, [[x - 23, y + h], [x + w + 23, y + h], [x + w + 12, y + h + 25], [x - 12, y + h + 25]], C.body2, C.ink, 3);
    box(ctx, x + w / 2 - 35, y + h + 5, 70, 9, 3, C.paper, null);
  }
  function tablet(ctx, x, y, w, h, t, fn = miniScreen) {
    box(ctx, x, y, w, h, 22, C.side, C.ink, 3.5);
    const sx = x + 12, sy = y + 16, sw = w - 24, sh = h - 37;
    box(ctx, sx, sy, sw, sh, 12, C.paper, null);
    ctx.save(); roundedPath(ctx, sx, sy, sw, sh, 12); ctx.clip(); fn(ctx, sx, sy, sw, sh, t); ctx.restore();
    line(ctx, x + w / 2 - 22, y + h - 11, x + w / 2 + 22, y + h - 11, C.muted, 2);
  }
  function keyboard(ctx, x = 147, y = 881, w = 435, h = 52) {
    box(ctx, x, y, w, h, 10, C.body, C.ink, 2.5);
    const keyW = (w - 40 - 10 * 7) / 11;
    for (let r = 0; r < 3; r++) for (let c = 0; c < 11; c++) box(ctx, x + 20 + c * (keyW + 7), y + 9 + r * 12, keyW, 7, 2, C.paper, null);
  }
  function desk(ctx) {
    polygon(ctx, [[145, 790], [1018, 790], [1116, 940], [64, 940]], matte(ctx, 64, 790, 1052, 150, C.desk, C.desk2), C.line, 2.5);
    box(ctx, 64, 940, 1052, 17, 5, C.body2, C.ink, 2.5);
    box(ctx, 126, 958, 21, 58, 4, C.body2, C.ink, 2.5);
    box(ctx, 1031, 958, 21, 58, 4, C.body2, C.ink, 2.5);
  }
  function notebook(ctx, x = 850, y = 879, w = 195, h = 47) {
    box(ctx, x, y + 7, w, h, 7, C.paper, C.ink, 2);
    box(ctx, x, y, w, h, 7, blend(C.body, C.accent, .20), C.ink, 2.5);
    line(ctx, x + 16, y + 3, x + 16, y + h - 3, C.muted, 2);
    line(ctx, x + 38, y + 15, x + w - 22, y + 15, C.paper, 2);
    line(ctx, x + 38, y + 27, x + w - 50, y + 27, C.paper, 2);
  }
  function headset(ctx, x = 697, y = 815, scale = 1) {
    ctx.save(); ctx.translate(x, y); ctx.scale(scale, scale);
    box(ctx, -5, 6, 10, 91, 4, C.body2, C.ink, 2.5);
    box(ctx, -48, 95, 96, 16, 8, C.body, C.ink, 2.5);
    ctx.beginPath(); ctx.arc(0, 0, 60, Math.PI, TAU); ctx.strokeStyle = C.ink; ctx.lineWidth = 11; ctx.stroke();
    ctx.beginPath(); ctx.arc(0, 0, 52, Math.PI + .1, TAU - .1); ctx.strokeStyle = C.body2; ctx.lineWidth = 5; ctx.stroke();
    box(ctx, -66, -8, 24, 64, 11, C.side, C.ink, 2.5);
    box(ctx, 42, -8, 24, 64, 11, C.side, C.ink, 2.5);
    line(ctx, 64, 43, 82, 61, C.ink, 3); line(ctx, 82, 61, 57, 69, C.ink, 3);
    box(ctx, 46, 64, 19, 9, 4, C.side, null);
    ctx.restore();
  }
  function microphone(ctx, x, y, scale = 1) {
    ctx.save(); ctx.translate(x, y); ctx.scale(scale, scale);
    box(ctx, -28, -126, 56, 91, 25, matte(ctx, -28, -126, 56, 91, C.body, C.body2), C.ink, 3);
    for (let i = 0; i < 5; i++) line(ctx, -17, -109 + i * 12, 17, -109 + i * 12, C.muted, 2);
    ctx.beginPath(); ctx.moveTo(-40, -70); ctx.lineTo(-40, -37); ctx.quadraticCurveTo(-40, -10, 0, -10); ctx.quadraticCurveTo(40, -10, 40, -37); ctx.lineTo(40, -70); ctx.strokeStyle = C.ink; ctx.lineWidth = 3; ctx.stroke();
    box(ctx, -6, -10, 12, 30, 4, C.body2, C.ink, 2);
    box(ctx, -53, 19, 106, 16, 8, C.body, C.ink, 2.5);
    ctx.restore();
  }
  function router(ctx, x, y, w = 157, h = 45, t = 0) {
    line(ctx, x + 23, y, x + 23, y - 47, C.ink, 4);
    line(ctx, x + w - 24, y, x + w - 24, y - 47, C.ink, 4);
    box(ctx, x, y, w, h, 12, C.body, C.ink, 2.5);
    for (let i = 0; i < 4; i++) circle(ctx, x + 22 + i * 17, y + h / 2, 3, blend(C.line, C.accent, .55 + .25 * Math.sin(TAU * t / 5 + i)));
    line(ctx, x + w - 34, y + 17, x + w - 18, y + 17, C.muted, 2);
    line(ctx, x + w - 34, y + 26, x + w - 18, y + 26, C.muted, 2);
  }
  function lock(ctx, x, y, s, p = 1) {
    const lift = (1 - p) * s * .15;
    ctx.beginPath(); ctx.moveTo(x - s * .23, y); ctx.lineTo(x - s * .23, y - s * .20 - lift);
    ctx.bezierCurveTo(x - s * .23, y - s * .56 - lift, x + s * .23, y - s * .56 - lift, x + s * .23, y - s * .20 - lift);
    ctx.lineTo(x + s * .23, y - lift); ctx.strokeStyle = C.ink; ctx.lineWidth = s * .065; ctx.stroke();
    box(ctx, x - s * .38, y - s * .04, s * .76, s * .56, s * .09, C.body, C.ink, 3);
    circle(ctx, x, y + s * .19, s * .06, C.accent); line(ctx, x, y + s * .24, x, y + s * .35, C.accent, s * .05);
  }
  function shield(ctx, x, y, s, p = 1) {
    ctx.beginPath(); ctx.moveTo(x, y - s * .5); ctx.lineTo(x + s * .4, y - s * .30); ctx.lineTo(x + s * .36, y + s * .12);
    ctx.quadraticCurveTo(x + s * .25, y + s * .36, x, y + s * .53); ctx.quadraticCurveTo(x - s * .25, y + s * .36, x - s * .36, y + s * .12); ctx.lineTo(x - s * .4, y - s * .30); ctx.closePath();
    ctx.fillStyle = blend(C.paper, C.green, .10); ctx.fill(); ctx.strokeStyle = C.ink; ctx.lineWidth = 3; ctx.stroke();
    if (p > .0001) check(ctx, x, y + s * .03, s * .43, C.green, p);
  }
  function badge(ctx, x, y, w, text, color = C.accent, opacity = 1) {
    box(ctx, x, y, w, 34, 12, blend(C.paper, color, .12), null);
    layer(ctx, opacity, () => label(ctx, text, x + w / 2, y + 17, 14, color, 'center', w - 24, 700));
  }
  function route(ctx, points, t, start, end, stop, fade, color = C.accent) {
    ctx.beginPath(); ctx.moveTo(...points[0]); for (let i = 1; i < points.length; i++) ctx.lineTo(...points[i]); ctx.strokeStyle = C.line; ctx.lineWidth = 2.5; ctx.stroke();
    const a = windowAlpha(t, start - .4, start, stop, fade);
    const lengths = [], total = points.slice(1).reduce((sum, p, i) => { const d = Math.hypot(p[0] - points[i][0], p[1] - points[i][1]); lengths.push(d); return sum + d; }, 0);
    const dist = phase(t, start, end) * total;
    let travelled = 0;
    for (let i = 0; i < lengths.length; i++) {
      if (dist <= travelled + lengths[i] || i === lengths.length - 1) {
        const p = clamp((dist - travelled) / lengths[i]);
        layer(ctx, a, () => circle(ctx, mix(points[i][0], points[i + 1][0], p), mix(points[i][1], points[i + 1][1], p), 5, color)); break;
      }
      travelled += lengths[i];
    }
  }
  function paint(ctx, cycleT, sceneProgress) {

    const t = cycleT;
    heading(ctx, 'Connected conference desk', 'Four workspaces linked through one clear meeting interface.', t);
    desk(ctx);
    monitor(ctx, 110, 320, 670, 400, t);
    laptop(ctx, 830, 642, 270, 180, t);
    keyboard(ctx, 140, 882, 435, 52);
    headset(ctx, 706, 819, .80);
    notebook(ctx, 851, 886, 193, 40);
    box(ctx, 601, 889, 38, 30, 6, C.side, C.ink, 2);
    line(ctx, 612, 897, 628, 897, C.paper, 2);
    circle(ctx, 620, 908, 2.5, C.accent);

  }
  return {paint, layout, background: C.bg};
})();

function draw(ctx, time, width, height) {
  const t = time;
  const duration = 20;
  const sceneCount = 1;
  const loopT = t % duration;
  const sceneDuration = duration / sceneCount;
  const currentScene = Math.floor(loopT / sceneDuration);
  const sceneProgress = (loopT % sceneDuration) / sceneDuration;
  const minSide = Math.min(width, height);
  if (!(width > 0 && height > 0 && minSide > 0)) return;
  const scale = Math.min(width / 1920, height / 1080, minSide / 1080);
  const cycleT = Number.isFinite(loopT) ? (loopT < 0 ? loopT + duration : loopT) : 0;
